// Product Interface
export interface NotificationChannel {
  send(recipient: string, message: string): Promise<boolean>;
  getChannelType(): string;
}

// Concrete Products
export class SlackNotificationChannel implements NotificationChannel {
  async send(recipient: string, message: string): Promise<boolean> {
    console.log(`[Slack Webhook] Sending to ${recipient}: ${message}`);
    return true;
  }
  getChannelType(): string { return "SLACK"; }
}

export class EmailNotificationChannel implements NotificationChannel {
  async send(recipient: string, message: string): Promise<boolean> {
    console.log(`[SMTP Outbound] Sending to ${recipient}: ${message}`);
    return true;
  }
  getChannelType(): string { return "EMAIL"; }
}

// Base Creator (Factory Method)
export abstract class NotificationDispatcher {
  // The Factory Method
  protected abstract createChannel(): NotificationChannel;

  // Template Orchestration Method
  public async dispatch(recipient: string, message: string): Promise<void> {
    const channel = this.createChannel();
    console.log(`[Audit] Dispatching via ${channel.getChannelType()}`);
    const success = await channel.send(recipient, message);
    if (!success) {
      throw new Error(`Delivery failed on channel: ${channel.getChannelType()}`);
    }
  }
}

// Concrete Creators
export class SlackDispatcher extends NotificationDispatcher {
  protected createChannel(): NotificationChannel {
    return new SlackNotificationChannel();
  }
}

export class EmailDispatcher extends NotificationDispatcher {
  protected createChannel(): NotificationChannel {
    return new EmailNotificationChannel();
  }
}
